package dev.veltraph.client.foraging.supply;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import dev.veltraph.client.world.BlockPos;
final class ForagingSupplyRuntimeTest {
    final Object player=new Object(),world=new Object(),connection=new Object(),menu=new Object();
    final ForagingSupplyRuntime.Scope scope=new ForagingSupplyRuntime.Scope(player,world,connection);
    final ForagingSupplyBindings.Resource sapling=new ForagingSupplyBindings.Resource("minecraft:dark_oak_sapling","Dark Oak Sapling","sapling",64,"shop sapling","Supply","Buy Saplings","offer",100,"Purse: ");
    final ForagingSupplyBindings.Resource bone=new ForagingSupplyBindings.Resource("minecraft:bone_meal","Bone Meal","bone",64,"shop bone","Supply","Buy Bonemeal","offer",100,"Purse: ");
    ForagingSupplyBindings bindings(){return new ForagingSupplyBindings(1,new BlockPos(0,1,0),new BlockPos(1,1,0),"Chest",Map.of(ForagingSupplyConfig.Type.SAPLING,sapling,ForagingSupplyConfig.Type.BONEMEAL,bone),10000);}
    List<ForagingSupplyRuntime.Stack> inventory(){return new ArrayList<>(Collections.nCopies(36,ForagingSupplyRuntime.Stack.EMPTY));}
    ForagingSupplyRuntime.Stack supply(ForagingSupplyBindings.Resource r,int n){return new ForagingSupplyRuntime.Stack(r.id(),r.name(),r.components(),n,false);}
    ForagingSupplyRuntime.Observation o(List<ForagingSupplyRuntime.Stack> items,long purse,Object m,List<ForagingSupplyRuntime.Stack> chest,boolean ack){return new ForagingSupplyRuntime.Observation(scope,10,items,true,true,purse,m,m==null?"":"Chest",chest,true,ack);}
    static final class Port implements ForagingSupplyRuntime.Port {int buys,opens,stores,releases;public boolean acquire(ForagingSupplyRuntime.Observation o,ForagingSupplyBindings.Resource r){buys++;return true;}public boolean open(ForagingSupplyRuntime.Observation o){opens++;return true;}public boolean store(ForagingSupplyRuntime.Observation o,int i){stores++;return true;}public boolean verifyStorage(ForagingSupplyRuntime.Observation o){return true;}public void release(){releases++;}}
    @Test void sourceDefaultIsSaplingAndUtilityDisabled(){assertEquals(ForagingSupplyConfig.Type.SAPLING,ForagingSupplyConfig.FORAGING_AUTO_FILL_TYPE.defaultValue());assertFalse(ForagingSupplyConfig.FORAGING_CHEST_FILL_ENABLED.defaultValue());assertEquals("",ForagingSupplyConfig.FORAGING_CHEST_FILL_BINDINGS.defaultValue());}
    @Test void bothModesExistingSelectedSupplySkipAcquisition(){for(var type:ForagingSupplyConfig.Type.values()){var items=inventory();items.set(10,supply(bindings().resources().get(type),64));var r=new ForagingSupplyRuntime();assertTrue(r.start(o(items,1000,null,List.of(),false),bindings(),type));assertEquals(ForagingSupplyRuntime.Stage.OPEN_CHEST,r.stage());}}
    @Test void absentSelectedSupplyDispatchesOnceAndPartialStops(){var r=new ForagingSupplyRuntime();var p=new Port();var items=inventory();assertTrue(r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING));r.tick(o(items,1000,null,List.of(),false),p);r.tick(o(items,1000,null,List.of(),false),p);assertEquals(1,p.buys);var partial=inventory();partial.set(9,supply(sapling,63));r.tick(o(partial,990,null,List.of(),true),p);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,r.stage());assertEquals(1,p.buys);}
    @Test void nativeAcquisitionAndExactStorageNeedFreshChest(){var r=new ForagingSupplyRuntime();var p=new Port();var items=inventory();r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);r.tick(o(items,1000,null,List.of(),false),p);items.set(9,supply(sapling,64));r.tick(o(items,990,null,List.of(),false),p);assertEquals(ForagingSupplyRuntime.Stage.ACQUIRE_ACK,r.stage());r.tick(o(items,990,null,List.of(),true),p);assertEquals(10,r.acquiredCost());r.tick(o(items,990,menu,List.of(ForagingSupplyRuntime.Stack.EMPTY),false),p);r.tick(o(items,990,menu,List.of(ForagingSupplyRuntime.Stack.EMPTY),false),p);assertEquals(1,p.stores);var empty=inventory();r.tick(o(empty,990,menu,List.of(supply(sapling,64)),true),p);assertEquals(ForagingSupplyRuntime.Stage.STORE_ACK,r.stage());r.tick(o(empty,990,new Object(),List.of(supply(sapling,64)),true),p);assertEquals(ForagingSupplyRuntime.Stage.STORE,r.stage());}
    @Test void protectedItemAndForeignInventoryDeltaNeverStored(){var items=inventory();items.set(9,new ForagingSupplyRuntime.Stack(sapling.id(),sapling.name(),sapling.components(),64,true));var r=new ForagingSupplyRuntime();r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);assertEquals(ForagingSupplyRuntime.Stage.BUY_RESOURCE,r.stage());var p=new Port();r.tick(o(items,1000,null,List.of(),false),p);var after=new ArrayList<>(items);after.set(10,supply(sapling,64));after.set(11,new ForagingSupplyRuntime.Stack("minecraft:diamond","Diamond","x",1,false));r.tick(o(after,990,null,List.of(),true),p);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,r.stage());}
    @Test void contextChangeAndCancelNeverRetry(){var items=inventory();var r=new ForagingSupplyRuntime();var p=new Port();r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);r.tick(new ForagingSupplyRuntime.Observation(new ForagingSupplyRuntime.Scope(player,world,new Object()),10,items,true,true,1000,null,"",List.of(),true,false),p);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,r.stage());assertEquals(0,p.buys);r.cancel(p);assertEquals(ForagingSupplyRuntime.Stage.CANCELLED,r.stage());}
    @Test void foreignChestTitleDoesNotBecomeOwned(){var items=inventory();items.set(9,supply(sapling,64));var r=new ForagingSupplyRuntime();var p=new Port();r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);r.tick(new ForagingSupplyRuntime.Observation(scope,10,items,true,true,1000,menu,"Foreign",List.of(ForagingSupplyRuntime.Stack.EMPTY),true,true),p);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,r.stage());assertEquals(0,p.stores);}
    @Test void laterUnrelatedDeltaCannotHideInsideSelectedResourceTotal(){var items=inventory();items.set(9,supply(sapling,64));items.set(15,new ForagingSupplyRuntime.Stack("minecraft:diamond_sword","Sword","gear",1,true));var r=new ForagingSupplyRuntime();var p=new Port();r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);var changed=new ArrayList<>(items);changed.set(15,ForagingSupplyRuntime.Stack.EMPTY);r.tick(o(changed,1000,null,List.of(),false),p);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,r.stage());assertEquals(0,p.opens);}
    @Test void partialStorageNativeAcknowledgmentDoesNotCreditFullStack(){var items=inventory();items.set(9,supply(sapling,64));var r=new ForagingSupplyRuntime();var p=new Port();r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);r.tick(o(items,1000,menu,List.of(ForagingSupplyRuntime.Stack.EMPTY),true),p);r.tick(o(items,1000,menu,List.of(ForagingSupplyRuntime.Stack.EMPTY),true),p);var after=inventory();r.tick(o(after,1000,new Object(),List.of(supply(sapling,63)),true),p);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,r.stage());assertEquals(1,p.stores);}
    @Test void exactNativeMergePreservesOriginalChestStackAndCreditsIssuedTotal(){var items=inventory();items.set(9,supply(sapling,32));var r=new ForagingSupplyRuntime();var p=new Port();r.start(o(items,1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);var chest=List.of(supply(sapling,40),ForagingSupplyRuntime.Stack.EMPTY);r.tick(o(items,1000,menu,chest,true),p);r.tick(o(items,1000,menu,chest,true),p);r.tick(o(inventory(),1000,new Object(),List.of(supply(sapling,64),supply(sapling,8)),true),p);assertEquals(ForagingSupplyRuntime.Stage.STORE,r.stage());assertEquals(1,p.stores);}
    @Test void revisionlessFinancialAttributionStopsUnknownWithoutRetry(){var r=new ForagingSupplyRuntime();var p=new Port();r.start(o(inventory(),1000,null,List.of(),false),bindings(),ForagingSupplyConfig.Type.SAPLING);r.unattributedAcquisition(p);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,r.stage());r.tick(o(inventory(),1000,null,List.of(),false),p);assertEquals(0,p.buys);assertEquals(1,p.releases);}
}
